export function correct(q,a=[]){return a.length===q.answer.length&&[...a].sort((x,y)=>x-y).every((v,i)=>v===[...q.answer].sort((x,y)=>x-y)[i]);}
export function shuffle(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
export function remaining(session,now=Date.now()){return Math.max(0,Math.ceil((session.deadline-now)/1000));}
export function validateBank(v){if(!Array.isArray(v)||!v.length||v.length>5000)throw new Error('题库需要包含1至5000道题的JSON数组。');const ids=new Set();for(const q of v){if(!q||typeof q.id!=='string'||!q.id||['__proto__','constructor','prototype'].includes(q.id)||ids.has(q.id))throw new Error('每道题需要唯一的字符串id。');ids.add(q.id);if(!['人员','过程','商业环境'].includes(q.domain)||!['预测','敏捷','混合'].includes(q.approach))throw new Error('领域或方法字段不正确。');if(!['topic','stem'].every(k=>typeof q[k]==='string'&&q[k].trim()))throw new Error('缺少考点或题干。');if(!Array.isArray(q.options)||q.options.length<2||q.options.length>8||q.options.some(x=>typeof x!=='string'||!x.trim()))throw new Error('选项须为2至8个非空字符串。');if(!Array.isArray(q.answer)||!q.answer.length||new Set(q.answer).size!==q.answer.length||q.answer.some(x=>!Number.isInteger(x)||x<0||x>=q.options.length))throw new Error('answer需要合法、不重复的选项下标，从0开始。');if(!Array.isArray(q.rationales)||q.rationales.length!==q.options.length||q.rationales.some(x=>typeof x!=='string'||!x.trim()))throw new Error('每个选项都需要对应解析。');}return v;}
export function score(questions,answers){const domains={};let total=0;for(const q of questions){const ok=correct(q,answers[q.id]||[]);total+=Number(ok);const d=domains[q.domain]??={right:0,total:0};d.total++;d.right+=Number(ok);}return {right:total,total:questions.length,percent:questions.length?Math.round(total/questions.length*100):0,domains};}
